-4a2f-897f-7047d0e1af9b", "pack_id": "548f06be-ccf4-426d-b82b-b424137a4438", "version_hash": "10665c5e3b39fcedd8ee34b0fdedae74", "choices_hash": "c19953d1d2573112ab8c91e6ae89221d", "item_hash": "3f967f409f5459d950101e3b573aa299", "old_path": null, "old_taxonomy_hash": "7476cfaa5268835789a2504ea81fd281a067ce0f74b47b946fa4960a874daa9c", "kind": "teaching_image", "new_version_id": "5f75f226-dba1-4457-8f92-f8a5761fba20", "new_version_num": 1, "png": "apstats-oht-2-1.png", "storage_path": "questions/apstats-oht-2.1/v1/65ffbc3e2a1900b15ac29cd9f531c37bd73a9132e4a5d0d468de2667c8b1d74f.png", "sha256": "65ffbc3e2a1900b15ac29cd9f531c37bd73a9132e4a5d0d468de2667c8b1d74f", "bytes": 42857, "alt_text": "Both bars total 100 percent of their own club. Chess: online 40 percent, not online 60 percent. Art: online 75 percent, not online 25 percent. Dark segments denote online; light segments denote not online. No membership counts are specified.", "long_description": "Both bars total 100 percent of their own club. Chess: online 40 percent, not online 60 percent. Art: online 75 percent, not online 25 percent. Dark segments denote online; light segments denote not online. No membership counts are specified.", "cells_before": [{"source": "task0065_oht_generated_2026_10_06", "created_at": "2026-10-06T15:34:26.649934+00:00", "is_primary": true, "skill_code": null, "topic_code": "2.1", "model_run_id": "TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)", "validated_at": null, "validated_by": null, "superseded_by": null, "content_item_id": "51917459-0390-4a2f-897f-7047d0e1af9b", "assignment_status": "authored", "content_item_cell_id": "ea384538-4223-418a-aea6-a45a7ed5c3a1", "validation_decision_id": null, "content_item_version_id": "5f75f226-dba1-4457-8f92-f8a5761fba20", "taxonomy_source_version": "dae3c72e-82ca-4960-9552-1b034bd347e5"}]}]$t$::jsonb) as t(content_key text,old_version_id uuid,version_hash text,item_hash text,choices_hash text,old_taxonomy_hash text,old_path text,storage_path text,sha256 text,bytes bigint,alt_text text,long_description text);
do $g$ begin
